-- Step 17.13: supervised Performance Marketing Agent orchestration.
create table public.marketing_agent_cases (id uuid primary key default gen_random_uuid(),case_ref text not null unique,case_type text not null check(case_type in('campaign','audience','budget','experiment','attribution')),provider_code text,campaign_ref text,status text not null default 'open' check(status in('open','investigating','awaiting_approval','approved','resolved','closed')),priority text not null default 'normal' check(priority in('low','normal','high','critical')),evidence jsonb not null default '{}' check(jsonb_typeof(evidence)='object'),recommendation jsonb not null default '{}' check(jsonb_typeof(recommendation)='object'),created_by uuid not null default auth.uid() references auth.users(id) on delete restrict,due_at timestamptz,created_at timestamptz not null default statement_timestamp(),updated_at timestamptz not null default statement_timestamp());
create index marketing_cases_queue_idx on public.marketing_agent_cases(status,priority,due_at); create index marketing_cases_created_by_idx on public.marketing_agent_cases(created_by);
create table public.marketing_agent_tasks(id uuid primary key default gen_random_uuid(),case_id uuid references public.marketing_agent_cases(id) on delete restrict,title text not null,status text not null default 'queued' check(status in('queued','running','waiting_human','completed','failed','escalated','cancelled')),result_summary jsonb not null default '{}' check(jsonb_typeof(result_summary)='object'),created_by uuid not null default auth.uid() references auth.users(id) on delete restrict,due_at timestamptz,created_at timestamptz not null default statement_timestamp()); create index marketing_tasks_queue_idx on public.marketing_agent_tasks(status,due_at);
create table public.marketing_agent_approvals(id uuid primary key default gen_random_uuid(),case_id uuid not null references public.marketing_agent_cases(id) on delete restrict,approval_type text not null check(approval_type in('campaign_launch','budget_increase','targeting_change','major_pause','paid_spend','experiment_activation','bulk_action')),requested_action text not null,evidence jsonb not null default '{}' check(jsonb_typeof(evidence)='object'),status text not null default 'pending' check(status in('pending','approved','rejected','cancelled','expired')),requested_by uuid not null default auth.uid() references auth.users(id) on delete restrict,decided_by uuid references auth.users(id) on delete restrict,decision_reason text,requested_at timestamptz not null default statement_timestamp(),decided_at timestamptz,check((status='pending' and decided_by is null and decided_at is null)or(status<>'pending' and decided_by is not null and decided_at is not null))); create index marketing_approvals_queue_idx on public.marketing_agent_approvals(status,requested_at);
create table public.marketing_agent_automations(id uuid primary key default gen_random_uuid(),automation_key text not null unique,name text not null,configuration jsonb not null default '{}' check(jsonb_typeof(configuration)='object'),status text not null default 'draft' check(status in('draft','pending_approval','active','paused','archived')),automatic_campaign_launch boolean not null default false check(not automatic_campaign_launch),automatic_budget_change boolean not null default false check(not automatic_budget_change),automatic_targeting_change boolean not null default false check(not automatic_targeting_change),automatic_major_pause boolean not null default false check(not automatic_major_pause),automatic_spend_commit boolean not null default false check(not automatic_spend_commit),created_by uuid not null default auth.uid() references auth.users(id) on delete restrict,approved_by uuid references auth.users(id),approved_at timestamptz,updated_at timestamptz not null default statement_timestamp(),check(status<>'active'or(approved_by is not null and approved_at is not null)));
create table public.marketing_agent_reports(id uuid primary key default gen_random_uuid(),report_type text not null check(report_type in('spend_roas','budget_pacing','experiment','attribution','audience_quality')),period_start timestamptz not null,period_end timestamptz not null,summary jsonb not null default '{}' check(jsonb_typeof(summary)='object'),generated_at timestamptz not null default statement_timestamp(),check(period_end>period_start));
create table private.marketing_agent_activity(id bigint generated always as identity primary key,case_id uuid references public.marketing_agent_cases(id) on delete set null,actor_type public.audit_actor_type not null,actor_id uuid references auth.users(id) on delete set null,action text not null,evidence jsonb not null default '{}' check(jsonb_typeof(evidence)='object'),occurred_at timestamptz not null default statement_timestamp()); create index marketing_activity_timeline_idx on private.marketing_agent_activity(occurred_at desc,id desc);
alter table public.marketing_agent_cases enable row level security;alter table public.marketing_agent_cases force row level security;alter table public.marketing_agent_tasks enable row level security;alter table public.marketing_agent_tasks force row level security;alter table public.marketing_agent_approvals enable row level security;alter table public.marketing_agent_approvals force row level security;alter table public.marketing_agent_automations enable row level security;alter table public.marketing_agent_automations force row level security;alter table public.marketing_agent_reports enable row level security;alter table public.marketing_agent_reports force row level security;alter table private.marketing_agent_activity enable row level security;alter table private.marketing_agent_activity force row level security;
revoke all on public.marketing_agent_cases,public.marketing_agent_tasks,public.marketing_agent_approvals,public.marketing_agent_automations,public.marketing_agent_reports from public,anon,authenticated;revoke all on private.marketing_agent_activity from public,anon,authenticated,service_role;grant select,insert,update on public.marketing_agent_cases,public.marketing_agent_tasks,public.marketing_agent_approvals,public.marketing_agent_automations to authenticated;grant select on public.marketing_agent_reports to authenticated;
create function private.is_step_17_13_marketing_admin(p_owner_only boolean default false)returns boolean language sql stable security definer set search_path='' as $$select(select auth.jwt()->>'aal')='aal2' and exists(select 1 from public.user_roles r where r.user_id=(select auth.uid())and r.is_active and r.revoked_at is null and(r.role='owner'::public.app_role or(not p_owner_only and r.role in('content'::public.app_role,'analyst'::public.app_role))));$$;revoke all on function private.is_step_17_13_marketing_admin(boolean) from public,anon,authenticated,service_role;grant execute on function private.is_step_17_13_marketing_admin(boolean) to authenticated;
create policy marketing_cases_read on public.marketing_agent_cases for select to authenticated using((select private.is_step_17_13_marketing_admin(false)));create policy marketing_cases_write on public.marketing_agent_cases for all to authenticated using((select private.is_step_17_13_marketing_admin(false)))with check(created_by=(select auth.uid())and(select private.is_step_17_13_marketing_admin(false)));create policy marketing_tasks_read on public.marketing_agent_tasks for select to authenticated using((select private.is_step_17_13_marketing_admin(false)));create policy marketing_tasks_write on public.marketing_agent_tasks for all to authenticated using((select private.is_step_17_13_marketing_admin(false)))with check(created_by=(select auth.uid())and(select private.is_step_17_13_marketing_admin(false)));create policy marketing_approvals_read on public.marketing_agent_approvals for select to authenticated using((select private.is_step_17_13_marketing_admin(false)));create policy marketing_approvals_request on public.marketing_agent_approvals for insert to authenticated with check(requested_by=(select auth.uid())and status='pending'and(select private.is_step_17_13_marketing_admin(false)));create policy marketing_approvals_decide on public.marketing_agent_approvals for update to authenticated using((select private.is_step_17_13_marketing_admin(true)))with check(decided_by=(select auth.uid())and status in('approved','rejected','cancelled')and(select private.is_step_17_13_marketing_admin(true)));create policy marketing_automations_read on public.marketing_agent_automations for select to authenticated using((select private.is_step_17_13_marketing_admin(false)));create policy marketing_automations_write on public.marketing_agent_automations for all to authenticated using((select private.is_step_17_13_marketing_admin(true)))with check(created_by=(select auth.uid())and not automatic_campaign_launch and not automatic_budget_change and not automatic_targeting_change and not automatic_major_pause and not automatic_spend_commit and(select private.is_step_17_13_marketing_admin(true)));create policy marketing_reports_read on public.marketing_agent_reports for select to authenticated using((select private.is_step_17_13_marketing_admin(false)));create policy marketing_activity_deny on private.marketing_agent_activity as restrictive for all to anon,authenticated using(false)with check(false);
create function private.reject_marketing_activity_mutation()returns trigger language plpgsql security definer set search_path='' as $$begin raise exception 'marketing activity is append-only';end;$$;revoke all on function private.reject_marketing_activity_mutation() from public,anon,authenticated,service_role;create trigger marketing_activity_immutable before update or delete on private.marketing_agent_activity for each row execute function private.reject_marketing_activity_mutation();
